from pathlib import Path

scenario = Path("scenarios/missions/d66_lvl10-16_mission_01_blacksun.md")
s = scenario.read_text(encoding="utf-8")
old = """  - 対戦車砲は奇数ラウンドのみ発射する。
    - 対戦車砲の攻撃は民兵の攻撃回数とは合算せず、独立して処理する。対戦車砲が攻撃するたび、防御ロールの前に【着弾対象ロール】として1d6を振る。奇数なら分隊長、偶数なら分隊員側を攻撃対象とする。民兵側の攻撃はCore v1.01の通常の【敵戦闘集団】として処理する。
    - 分隊員側が対象となった場合、通常どおり防御ロールを行い、防御に失敗したら【被弾ロール】で実際に被弾する隊員を決定する。攻撃対象となれる分隊員が1名もいない場合は、分隊長を対象とする。
    - 対象確定後、その対象について通常どおり防御ロールを行う。防御ロールの出目が1(ファンブル)の場合は2ダメージを受ける。
"""
new = """  - 対戦車砲は奇数ラウンドのみ発射する。
    - 対戦車砲の攻撃は民兵の攻撃回数とは合算せず、独立して処理する。対戦車砲が攻撃するたび、防御ロールの前に【着弾対象ロール】として1d6を振る。奇数なら分隊長、偶数なら分隊員側を攻撃対象とする。民兵側の攻撃はCore v1.01の通常の【敵戦闘集団】として処理する。
    - 【着弾対象ロール】が偶数で、攻撃対象となれる分隊員が1名もいない場合は、分隊長を攻撃対象とする。
    - 対象確定後、その対象について【防御ロール】を1回だけ行う。分隊員側が対象となって防御に失敗した場合は、【被弾ロール】で実際に被弾する隊員を決定する。
    - 防御ロールの出目が1(ファンブル)の場合は2ダメージを受ける。
"""
if s.count(old) != 1:
    raise SystemExit(f"anti-tank defense block count must be 1, got {s.count(old)}")
scenario.write_text(s.replace(old, new, 1), encoding="utf-8")

audit = Path("docs/SCENARIO_V1_01_RESOURCE_BALANCE_AUDIT.md")
a = audit.read_text(encoding="utf-8")
heading = "## 33. Black Sun 3周目最終戦の対戦車砲防御ロール手順 — 明確化済み"
section = """

## 33. Black Sun 3周目最終戦の対戦車砲防御ロール手順 — 明確化済み

追加監査により、対戦車砲の分隊員側対象処理に「通常どおり防御ロール」と「対象確定後、その対象について通常どおり防御ロール」が重複しており、防御ロールを2回行うようにも読める状態を確認したため、処理順のみ明確化した。

- 【着弾対象ロール】で奇数なら分隊長、偶数なら分隊員側を選ぶ既存仕様は変更しない。
- 偶数で攻撃対象となれる分隊員が0名なら、既存仕様どおり分隊長を対象とする。
- 対象確定後に【防御ロール】を行う回数は1回のみ。
- 分隊員側が対象で防御失敗した場合、その後に【被弾ロール】で実際の被弾者を決定する。
- 防御ロール出目1の2ダメージ処理は変更しない。

これは二重防御ロールを意図した変更ではなく、既存処理を一意に読めるようにした非ゲームプレイ変更である。
"""
if heading not in a:
    audit.write_text(a.rstrip() + section + "\n", encoding="utf-8")
